contoh.Diskon.java:
// Diskon.java
public interface Diskon {
    int potong(int harga);
}

contoh.DiskonPersen.java:
// DiskonPersen.java
public class DiskonPersen implements Diskon {
    private int persen;

    public DiskonPersen(int persen) {
        this.persen = persen;
    }

    @Override
    public int potong(int harga) {
        return harga - harga * persen / 100;
    }
}

contoh.DiskonTetap.java:
// DiskonTetap.java
public class DiskonTetap implements Diskon {
    private int jumlah;

    public DiskonTetap(int jumlah) {
        this.jumlah = jumlah;
    }

    @Override
    public int potong(int harga) {
        return Math.max(0, harga - jumlah);
    }
}

contoh.Kasir.java:
// Kasir.java
public class Kasir {
    public static int hitung(int harga, Diskon diskon) {
        return diskon.potong(harga);
    }
}
